<?php
define('ML_APP',true);define('ML_ROOT',__DIR__.'/..');require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);require_once __DIR__.'/../core/Version.php';require_once __DIR__.'/../core/DB.php';require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/RateLimit.php';if(php_sapi_name()!=='cli'){http_response_code(404);exit('Not Found');}$a=microtime(true);$b=array('action'=>'rate_prune','version'=>ML_APP_VERSION,'started_at'=>date('Y-m-d H:i:s'));try{$b['rate_deleted']=\Core\RateLimit::prune(86400);}catch(\Throwable $c){$b['rate_error']=$c->getMessage();}try{$d=ML_ROOT.'/cache';if(is_dir($d)){$e=time();$f=0;foreach(glob($d.'/*.cache')as $g){if($e-@filemtime($g)>86400*30){if(@unlink($g)){$f++;}}}$b['cache_deleted']=$f;}}catch(\Throwable $c){$b['cache_error']=$c->getMessage();}try{$h=\Core\DB::pdo();$i=$h->query("SELECT PARTITION_NAME FROM information_schema.PARTITIONS
